342	        if (Object.prototype.hasOwnProperty.call(context_dictionaryToCreate, context_w)) {
343	          if (context_w.charCodeAt(0) < 256) {
344	            for (i = 0; i < context_numBits; i++) {
345	              context_data_val = context_data_val << 1;
346	              if (context_data_position == bitsPerChar - 1) {
347	                context_data_position = 0;
348	                context_data.push(getCharFromInt(context_data_val));
